const body = $input.first().json.body || $input.first().json;
const msg = body.message || '';
const userId = body.userId;
const role = body.role;

let blocked = null;
if (!msg || msg.trim().length === 0) blocked = 'Message vide.';
else if (msg.length > 600) blocked = 'Message trop long.';
else if (!userId || !role) blocked = 'userId et role obligatoires.';
else {
  const forbidden = ['ignore previous','ignore all','jailbreak',
    'forget your instructions','system:','DROP TABLE','--'];
  if (forbidden.some(w => msg.toLowerCase().includes(w.toLowerCase())))
    blocked = 'Message non autorisé.';
}

if (blocked) {
  return [{ json: { blocked: true, isDocQuestion: false, error: blocked } }];
}

const docKeywords = ['document','fichier','pdf','résumé','resume',
  'résume','contenu','explique','td','tp','polycopié','support',
  'cours','chapitre','parle de','traite de','c\'est quoi','de quoi'];
const isDocQuestion = docKeywords.some(k => msg.toLowerCase().includes(k));

return [{
  json: {
    blocked: false,
    isDocQuestion,
    message: msg.trim(),
    userId: parseInt(userId),
    role: role.toUpperCase()
  }
}];

const guardrail = $('Guardrail IN').first().json;
const db = $('MySQL - Contexte Utilisateur').first().json;

const role = guardrail.role;
const nom = (db.prenom || '') + ' ' + (db.nom || '');

function safeArray(val) {
  if (!val) return [];
  if (Array.isArray(val)) return val;
  if (typeof val === 'string') {
    try { return JSON.parse(val); } catch(e) { return []; }
  }
  return [];
}

const notes         = safeArray(db.notes);
const annoncesEtu   = safeArray(db.annonces_etudiant);
const annoncesPro   = safeArray(db.annonces_prof);
const matieres      = safeArray(db.matieres_prof);
const seances       = safeArray(db.prochaines_seances);

let systemPrompt = '';

if (role === 'ETUDIANT' || db.role_code === 2 || db.role_code === '2') {

  const notesText = notes.length > 0
    ? notes.map(n => '  - ' + n.matiere + ' : ' + n.note + '/20 (' + n.type + ' du ' + n.date + ')').join('\n')
    : '  Aucune note enregistrée.';

  const seancesText = seances.length > 0
    ? seances.map(s => '  - ' + s.date + ' de ' + s.debut + ' à ' + s.fin + ' | ' + s.matiere + ' (' + s.type + ') Salle: ' + (s.salle || 'non précisée')).join('\n')
    : '  Aucune séance à venir enregistrée dans la plateforme.';

  const annoncesText = annoncesEtu.length > 0
    ? annoncesEtu.map(a => '  - [' + a.urgent + '] ' + a.titre + ' (' + a.date + ') : ' + a.contenu).join('\n')
    : '  Aucune annonce.';

  systemPrompt = `Tu es l'assistant intelligent de la plateforme MyCampus.
Tu parles avec l'étudiant ${nom}.

=== INFORMATIONS ÉTUDIANT ===
- Apogée     : ${db.apogee || 'N/A'}
- Niveau     : ${db.niveau || 'N/A'}
- Semestre   : ${db.semestre_actuel || 'N/A'}
- Classe     : ${db.classe || 'N/A'}
- Statut     : ${db.etat_inscription || 'N/A'}
- Présences  : ${db.presences || 'Non disponible'}

=== NOTES ===
${notesText}

=== PROCHAINES SÉANCES ===
${seancesText}

=== ANNONCES ===
${annoncesText}

=== RÈGLES IMPORTANTES ===
- Réponds UNIQUEMENT avec les données ci-dessus.
- Si une information n'est pas dans ces données, réponds :
  "Cette information n'est pas disponible dans la plateforme."
- Ne jamais inventer de dates, notes, salles ou horaires.
- Réponds en français, de façon concise et bienveillante.`;

} else if (role === 'PROFESSEUR' || db.role_code === 1 || db.role_code === '1') {

  const matieresText = matieres.length > 0
    ? matieres.map(m => '  - ' + m.matiere + ' → Classe ' + m.classe + ' (' + m.annee + ')').join('\n')
    : '  Aucune affectation enregistrée.';

  const annoncesText = annoncesPro.length > 0
    ? annoncesPro.map(a => '  - [' + a.urgent + '] ' + a.titre + ' (' + a.date + ') : ' + a.contenu).join('\n')
    : '  Aucune annonce.';

  systemPrompt = `Tu es l'assistant intelligent de la plateforme MyCampus.
Tu parles avec le professeur ${nom}.

=== INFORMATIONS PROFESSEUR ===
- Grade       : ${db.grade_prof || 'N/A'}
- Spécialité  : ${db.specialite || 'N/A'}

=== MATIÈRES ENSEIGNÉES ===
${matieresText}

=== ANNONCES ===
${annoncesText}

=== RÈGLES IMPORTANTES ===
- Réponds UNIQUEMENT avec les données ci-dessus.
- Si une information n'est pas dans ces données, réponds :
  "Cette information n'est pas disponible dans la plateforme."
- Ne jamais inventer de données.
- Réponds en français, de façon professionnelle.`;

} else {

  systemPrompt = `Tu es l'assistant intelligent de la plateforme MyCampus.
Tu parles avec l'administrateur ${nom}.
Tu as accès à toutes les informations de la plateforme.

=== RÈGLES ===
- Réponds de façon précise et complète.
- Réponds en français.`;

}

return [{
  json: {
    systemPrompt,
    userMessage: guardrail.message,
    userId: guardrail.userId,
    role
  }
}];

// Basic LLM Chain retourne la réponse dans $json.text
const reply = $input.first().json.text
  || $input.first().json.output
  || $input.first().json.response
  || $input.first().json.content
  || '';

if (!reply || reply.trim().length < 3) {
  return [{ json: { reply: "Je n'ai pas pu générer une réponse.", ok: true } }];
}

const sensitive = ['mot de passe', 'password', '$2a$'];
if (sensitive.some(w => reply.toLowerCase().includes(w))) {
  return [{ json: { reply: "Je ne peux pas afficher cette information.", ok: true } }];
}

return [{ json: { reply: reply.trim(), ok: true } }];

