const msg = $('Guardrail IN').first().json.message.toLowerCase();
const fichiers = $input.all().map(i => i.json);

if (fichiers.length === 0) {
  return [{ json: {
    fichierTrouve: false,
    reponseDirecte: "Aucun document disponible pour toi dans la plateforme.",
    chemin: null
  }}];
}

let fichierChoisi = null;

// Cherche par matière mentionnée dans le message
fichierChoisi = fichiers.find(f =>
  f.matiere && msg.includes(f.matiere.toLowerCase().substring(0, 5))
);

// Cherche par type TD / TP / cours
if (!fichierChoisi) {
  if (msg.includes(' td ') || msg.startsWith('td ') || msg.endsWith(' td'))
    fichierChoisi = fichiers.find(f => f.type_seance === 'TD');
  else if (msg.includes(' tp ') || msg.startsWith('tp ') || msg.endsWith(' tp'))
    fichierChoisi = fichiers.find(f => f.type_seance === 'TP');
  else if (msg.includes('cours'))
    fichierChoisi = fichiers.find(f => f.type_seance === 'COURS');
}

// Par défaut : le fichier le plus récent
if (!fichierChoisi) fichierChoisi = fichiers[0];

const listeDisponible = fichiers.map(f =>
  '• ' + f.nom_original + ' — ' + f.matiere + ' (' + f.type_seance + ')'
).join('\n');

return [{ json: {
  fichierTrouve: true,
  chemin: fichierChoisi.chemin,
  nomFichier: fichierChoisi.nom_original,
  matiere: fichierChoisi.matiere,
  typeSeance: fichierChoisi.type_seance,
  listeDisponible,
  userMessage: $('Guardrail IN').first().json.message
}}];

const info = $('Choisir Fichier').first().json;
const texte = $input.first().json.text || '';

const texteCoupe = texte.length > 20000
  ? texte.substring(0, 20000) + '\n[document tronqué]'
  : texte;

const userMessage = info.userMessage;
const isResume = /résumé|resume|résume|résumer|de quoi|c'est quoi|parle de|traite/i.test(userMessage);

const systemPrompt = `Tu es l'assistant de la plateforme MyCampus.
Tu analyses le document suivant :

Nom     : ${info.nomFichier}
Matière : ${info.matiere}
Type    : ${info.typeSeance}

=== CONTENU ===
${texteCoupe}
=== FIN ===

${isResume
  ? `Fais un résumé clair et structuré :
• Introduction : de quoi parle ce document (2-3 phrases)
• Points clés : les 5 points les plus importants
• À retenir : ce que l'étudiant doit absolument savoir`
  : `Réponds précisément à la question en te basant UNIQUEMENT sur le contenu du document.
Si la réponse n'est pas dans le document, dis-le clairement.`
}
Réponds en français, de façon claire et pédagogique.`;

return [{ json: { systemPrompt, userMessage } }];

// Basic LLM Chain retourne la réponse dans $json.text
const reply = $input.first().json.text
  || $input.first().json.output
  || $input.first().json.response
  || $input.first().json.content
  || '';

if (!reply || reply.trim().length < 3) {
  return [{ json: { reply: "Je n'ai pas pu générer une réponse.", ok: true } }];
}

const sensitive = ['mot de passe', 'password', '$2a$'];
if (sensitive.some(w => reply.toLowerCase().includes(w))) {
  return [{ json: { reply: "Je ne peux pas afficher cette information.", ok: true } }];
}

return [{ json: { reply: reply.trim(), ok: true } }];
